def img(name,alt,cls='',eager=False):
 return f'<img class="{cls}" src="assets/images/{name}.webp" srcset="assets/images/{name}-480.webp 480w, assets/images/{name}.webp 1200w" sizes="(max-width: 640px) 100vw, 50vw" alt="{escape(alt)}" width="1200" height="800" loading="{"eager" if eager else "lazy"}"'+(' fetchpriority="high"' if eager else '')+'>'
def link(text,url='eye-test-booking.html',secondary=False):return f'<a class="button {"secondary" if secondary else ""}" href="{url}">{text}<span aria-hidden="true">→</span></a>'
def actions(primary='Explore eyewear',url='products.html',second='Book an eye test',url2='eye-test-booking.html'):
 return '<div class="actions">'+link(primary,url)+(link(second,url2,True) if second else '')+'</div>'
def intro(kicker,title,desc='',cta=''):
 return f'<div class="section-heading"><div><p class="eyebrow">{kicker}</p><h2>{title}</h2>'+ (f'<p>{desc}</p>' if desc else '')+f'</div>{cta}</div>'
def sec(content,cls='',id=''):
 return f'<section class="section {cls}"'+(f' id="{id}"' if id else '')+f'><div class="container">{content}</div></section>'
def hero(kicker,title,desc,image,cta=None,cls=''):
 return sec(f'<div class="split hero-grid"><div class="hero-copy"><p class="eyebrow"><span class="eyebrow-line"></span>{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p>{cta or actions()}<div class="hero-note"><span class="tiny-eye" aria-hidden="true">◎</span> Thoughtful frames. Personal care. A clearer everyday.</div></div><div class="hero-media">{img(image,desc,eager=True)}<span class="image-caption">A fresh perspective, beautifully framed.</span></div></div>','hero '+cls)
def split(kicker,title,desc,image,cta=None,reverse=False,extra='',cls=''):
 return sec(f'<div class="split {"reverse" if reverse else ""}"><div class="image-block">{img(image,title)}</div><div class="copy">{intro(kicker,title,desc)}{extra}{cta or ""}</div></div>',cls)
def cards(items,cls='grid-3'):
 return f'<div class="grid {cls}">'+''.join(f'<article class="card"><span class="card-number">{i+1:02}</span><h3>{x[0]}</h3><p>{x[1]}</p>'+ (f'<a class="text-link" href="{x[2]}">Learn more <span aria-hidden="true">→</span></a>' if len(x)>2 else '')+'</article>' for i,x in enumerate(items))+'</div>'
def icon(name):
 text=(ROOT/'assets/icons'/(name+'.svg')).read_text()
 return '<span class="feature-icon" aria-hidden="true">'+text+'</span>'
def features(title='Care that sees the whole you.',kicker='THE OCULIS DIFFERENCE'):
 content=cards([('People before prescriptions','A careful conversation and an appointment at your pace.','services.html'),('Lenses for your life','Thoughtful options, explained in clear everyday language.','service-details.html'),('A comfortable fit','Considered adjustments to help your frames feel like yours.','services.html'),('A little expert guidance','Personal support, from your first try-on to aftercare.','contact.html')],'grid-4')
 for i,name in enumerate(['eye','shield-check','glasses','scan-face']):
  content=content.replace(f'<span class="card-number">{i+1:02}</span>',icon(name),1)
 return sec(intro(kicker,title)+content,'alt')
def steps(title='A clearer path to your next pair.',kicker='SIMPLE FROM THE START',appointment=False):
 if appointment:
  return sec(intro(kicker,title)+cards([('Talk about your vision','Share your current glasses, daily needs and questions.'),('A considered examination','Complete the checks your eye-care professional recommends.'),('Understand the findings','Discuss your results, prescription and appropriate next steps.'),('Plan your follow-up','Explore lens options and any recommended ongoing care.')],'grid-4'),'steps')
 return sec(intro(kicker,title)+cards([('Discover your style','Tell us about your day, your taste and what you need.'),('Find your frame','Explore shapes, materials and sizes with a little guidance.'),('Choose your lenses','Discuss your prescription and suitable lens options.'),('Make it yours','Finish with a considered fitting and practical care advice.')],'grid-4'),'steps')
def cta(title='Good vision starts with a conversation.',desc='Find your frames. Ask your questions. Take a little time for your eyes.',label='Book an eye test',url='eye-test-booking.html'):
 return sec(f'<div class="cta-panel"><div><p class="eyebrow">WE’RE HERE FOR YOU</p><h2>{title}</h2><p>{desc}</p></div>{link(label,url)}</div>','cta-section')
def product_card(p,unique_image=None):
 return f'<article class="product-card" data-id="{p["id"]}"><a class="product-image" href="product-details.html?id={p["id"]}" aria-label="View {p["name"]}">{img(unique_image or p["image"],p["color"]+" "+p["style"].lower()+" eyeglasses")}<span class="product-tag">{p["style"]}</span><span class="image-arrow" aria-hidden="true">→</span></a><div class="product-info"><div><p class="small">{p["color"]}</p><h3><a href="product-details.html?id={p["id"]}">{p["name"]}</a></h3></div><span class="price">${p["price"]}</span></div><a class="text-link small" href="product-details.html?id={p["id"]}">View details <span aria-hidden="true">→</span></a></article>'
def product_grid(indices,cls='grid-4',unique_prefix=None):
 return f'<div class="grid {cls}">'+''.join(product_card(PRODUCTS[i],f'{unique_prefix}-{i}' if unique_prefix else None) for i in indices)+'</div>'
def article_card(a,unique=None):
 return f'<article class="article-card"><a class="article-image" href="blog-details.html?id={a["id"]}">{img(unique or a["image"],a["title"])}</a><div class="article-body"><p class="eyebrow">{a["category"]} <span>· {a["read"]}</span></p><h3><a href="blog-details.html?id={a["id"]}">{a["title"]}</a></h3><p>{a["desc"]}</p><a class="text-link" href="blog-details.html?id={a["id"]}">Read the story <span aria-hidden="true">→</span></a></div></article>'
def faq(items):return '<div class="faq">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in items)+'</div>'
FAQ=[('Do I need an appointment to browse?','You can browse our demo collection at any time. For a real store, replace this answer with your walk-in and appointment policy.'),('Can I bring my current prescription?','Bring your existing glasses and prescription to discuss your needs. An eye-care professional can advise if a new examination is appropriate.'),('Is my appointment confirmed online?','This template demonstrates an enquiry only. No real appointment is booked, and no live availability is connected.'),('Can you help me choose a frame?','The fitting consultation considers the bridge, temple length, lens position and your personal preferences.')]
def newsletter(title='A fresh perspective, in your inbox.'):
 return sec(f'<div class="newsletter"><div><p class="eyebrow">THE OCULIS EDIT</p><h2>{title}</h2><p>Frame inspiration and thoughtful everyday care. Demo subscription.</p></div><form class="demo-form newsletter-form" data-kind="newsletter" novalidate><label for="newsletter-email">Email address</label><div class="input-button"><input id="newsletter-email" name="email" type="email" autocomplete="email" placeholder="Your email address" required><button class="button" type="submit">Subscribe <span aria-hidden="true">→</span></button></div><span class="field-error" id="newsletter-email-error"></span><p class="form-status" role="status" aria-live="polite"></p><p class="small">Demo only. Your email is not stored or sent.</p></form></div>','alt')
def field(label,name,type='text',required=True,options=None):
 attrs=f'id="{name}" name="{name}"'+(' required' if required else '')+f' aria-describedby="{name}-error"'
 if options:control=f'<select {attrs}><option value="">Select {label.lower()}</option>'+''.join(f'<option>{x}</option>' for x in options)+'</select>'
 elif type=='textarea':control=f'<textarea {attrs} rows="4"'+(' maxlength="2000"' if name=='message' else '')+'></textarea>'
 else:control=f'<input {attrs} type="{type}"'+(' autocomplete="'+{'name':'name','email':'email','phone':'tel'}.get(name,'off')+'"')+(' minlength="2"' if name=='name' else '')+'>'
 return f'<div class="field {"wide" if type=="textarea" else ""}"><label for="{name}">{label}'+(' <span aria-hidden="true">*</span>' if required else ' <span class="optional">(optional)</span>')+f'</label>{control}<span class="field-error" id="{name}-error"></span></div>'
def form(kind):
 if kind=='booking':fields=field('Appointment service','service',options=['Comprehensive eye examination','Prescription lens consultation','Frame fitting & adjustment'])+field('Preferred date','date','date')+field('Preferred time (demo slots)','time',options=['09:00 AM','10:30 AM','12:00 PM','02:00 PM','03:30 PM','05:00 PM'])
 else:fields=''
 fields+=field('Full name','name')+field('Email address','email','email')+field('Phone number','phone','tel',kind=='booking')
 if kind=='contact':fields+=field('Subject','subject',options=['Product enquiry','Eye test enquiry','Frame fitting','Other'])
 fields+=field('Notes' if kind=='booking' else 'Message','notes' if kind=='booking' else 'message','textarea',kind!='booking')
 return f'<form class="demo-form form-grid" data-kind="{kind}" novalidate>{fields}<p class="small wide">'+('Sample slots only; availability is not live. Please avoid including medical history or sensitive information.' if kind=='booking' else 'This is a demonstration form. Your message is not sent or stored.')+f'</p><button class="button" type="submit">{"Request an appointment" if kind=="booking" else "Send enquiry"} <span aria-hidden="true">→</span></button><p class="form-status wide" role="status" aria-live="polite"></p></form>'
def chips(items,attr='style'):
 return '<div class="chips">'+''.join(f'<button type="button" class="chip" data-preset="{escape(x)}" data-filter="{attr}">{x}</button>' for x in items)+'</div>'
def add(file,title,sections):PAGES[file]=(title,sections)
