add('blog-details.html','A little care. A clearer everyday.',[
sec('<div class="article-header"><p class="eyebrow" id="article-category">FRAME CARE / THE OCULIS JOURNAL</p><h1 id="article-title">A little care.<br>A clearer everyday.</h1><p class="lead" id="article-description">A few thoughtful habits can make caring for your favourite frames feel like second nature.</p><div class="article-meta"><span>By the Oculis editorial team</span><span id="article-date">October 20, 2026</span><span id="article-read">4 min read</span></div>'+img('blog-detail','Woman wearing round eyeglasses reading a hardcover book',eager=True)+'</div>','page-top'),
sec('<div class="article-layout"><article class="prose" id="article-prose"><p class="lead">Your glasses go everywhere you do. A little everyday attention helps keep them ready for whatever comes next.</p><h2 id="clean">Start with a gentle clean.</h2><p>Dust and grit can collect on your lenses during the day. Before wiping them, rinse away loose particles with lukewarm water. Use a cleaner suitable for your particular lenses and a clean microfiber cloth, following the care advice supplied with your glasses.</p><p>Avoid using the hem of a shirt or a paper towel. A dedicated cloth, washed regularly without fabric softener, is a simple addition to your everyday routine.</p><h2 id="store">Give them a place to rest.</h2><p>When you take your glasses off, put them in a protective case. Keep the case away from direct heat, and avoid leaving your eyewear on a car dashboard or beside a hot appliance.</p><h2 id="fit">Notice how they feel.</h2><p>If your glasses slide, pinch or sit unevenly, ask an optical professional for an adjustment. Small fit changes are best handled with suitable tools and an understanding of the frame material.</p><h2 id="routine">Make care a small routine.</h2><p>Keep a case and cloth where you naturally put your glasses down. Simple, repeatable habits make it easier to look after a pair you enjoy wearing.</p><p class="small">Original general information for a fictional demonstration journal. For personal eye-health questions, speak with a qualified eye-care professional.</p></article><aside class="article-sidebar"><p class="eyebrow">IN THIS STORY</p><nav aria-label="Article contents"><a href="#clean">A gentle clean</a><a href="#store">Thoughtful storage</a><a href="#fit">A comfortable fit</a><a href="#routine">Your everyday routine</a></nav><hr><h3>A little more to explore.</h3><a class="text-link" href="blog.html">All journal categories →</a><a class="text-link" href="services.html">Explore our care →</a></aside></div>'),
sec(intro('YOUR EVERYDAY CHECKLIST','Small habits. Thoughtfully repeated.')+'<ul class="check-list checklist-grid"><li>Keep a clean microfiber cloth close by.</li><li>Rinse away dust before wiping lenses.</li><li>Use a protective case between wears.</li><li>Keep frames away from direct heat.</li><li>Ask for help with fit and adjustments.</li><li>Follow your lens supplier’s care guidance.</li></ul>','alt'),
sec('<div class="author-panel"><span class="author-mark" aria-hidden="true">◎</span><div><p class="eyebrow">BEHIND THE STORY</p><h3>The Oculis editorial team</h3><p>Original demo stories about considered eyewear and everyday care.</p></div><div class="article-navigation"><a href="blog-details.html?id=screen-breaks">← Previous story</a><a href="blog-details.html?id=lens-guide">Next story →</a></div></div>'),
sec(intro('KEEP YOUR CURIOSITY','Another fresh perspective.')+'<div class="grid grid-3">'+''.join(article_card(a,'related-article-'+a['id']) for a in ARTICLES[1:4])+'</div>','alt')
])
